typedef _Atomic(signed char) AtomicI8;typedef _Atomic(short) AtomicI16;typedef _Atomic(_Bool) AtomicBool;
struct Byte{signed char value;};struct Short{short value;};
AtomicI8 atomic_i8(AtomicI8 x){return x;}
signed char plain_i8(signed char x){return x;}
struct Byte record_i8(struct Byte x){return x;}
AtomicI16 atomic_i16(AtomicI16 x){return x;}
short plain_i16(short x){return x;}
struct Short record_i16(struct Short x){return x;}
AtomicBool atomic_bool(AtomicBool x){return x;}
_Bool plain_bool(_Bool x){return x;}
extern AtomicI8 callback(AtomicI8);
AtomicI8 call_callback(AtomicI8 x){return callback(x);}
#define PARAMS(T) T a,T b,T c,T d,T e,T f,T g,T h,T i,T j,T k,T l
int atomic_many(PARAMS(AtomicI8)){return a+b+c+d+e+f+g+h+i+j+k+l;}
int plain_many(PARAMS(signed char)){return a+b+c+d+e+f+g+h+i+j+k+l;}
int record_many(PARAMS(struct Byte)){return a.value+b.value+c.value+d.value+e.value+f.value+g.value+h.value+i.value+j.value+k.value+l.value;}

