#![no_std]
#[repr(C)]pub struct Byte{pub value:i8}
#[repr(C)]pub struct Short{pub value:i16}
#[no_mangle]pub extern "C" fn plain_i8(x:i8)->i8{x}
#[no_mangle]pub extern "C" fn record_i8(x:Byte)->Byte{x}
#[no_mangle]pub extern "C" fn plain_i16(x:i16)->i16{x}
#[no_mangle]pub extern "C" fn record_i16(x:Short)->Short{x}
#[no_mangle]pub extern "C" fn plain_bool(x:bool)->bool{x}
#[no_mangle]pub extern "C" fn record_many(a:Byte,b:Byte,c:Byte,d:Byte,e:Byte,f:Byte,g:Byte,h:Byte,i:Byte,j:Byte,k:Byte,l:Byte)->i32{a.value as i32+b.value as i32+c.value as i32+d.value as i32+e.value as i32+f.value as i32+g.value as i32+h.value as i32+i.value as i32+j.value as i32+k.value as i32+l.value as i32}

#[no_mangle] pub extern "C" fn arg_i8(x:i8)->i32{x as i32}
#[no_mangle] pub extern "C" fn arg_i16(x:i16)->i32{x as i32}
#[no_mangle] pub extern "C" fn branch_i16(x:i16)->i16{if x<0{x+1}else{x-1}}
#[no_mangle] pub extern "C" fn arg_u8(x:u8)->u32{x as u32}
#[no_mangle] pub extern "C" fn arg_u16(x:u16)->u32{x as u32}

