use toucan_bindings::{generate, Options, RustTarget};
use toucan_semantic::analyze_with_profile;
use toucan_target::{Compiler, CompilerProfile, Target};
fn main(){let args:Vec<_>=std::env::args().collect();let compiler=if args[2]=="clang"{Compiler::Clang}else{Compiler::Gnu};let profile=CompilerProfile::new(Target::parse(&args[1]).unwrap(),compiler).unwrap();let input=std::fs::read_to_string("api.h").unwrap();let analysis=analyze_with_profile(&input,profile,&Default::default()).unwrap();let options=Options{rust_target:RustTarget::RUST_1_64,rustified_enums:true,blocklist_functions:if compiler==Compiler::Clang{["c_i8","c_i16","c_b","c_many","c_callback_i8","c_callback_i16","c_callback_b","c_narrow_stress"].map(str::to_owned).to_vec()}else{vec![]},..Options::default()};print!("{}",generate(analysis.unit(),&options).unwrap().source);}

